import glob,struct

def classes(data):
    assert data[:4]==b'\xca\xfe\xba\xbe'
    n=struct.unpack('>H',data[8:10])[0]; p=10; consts=[None]
    for _ in range(n-1):
        tag=data[p]; p+=1
        if tag==1:
            ln=struct.unpack('>H',data[p:p+2])[0]; p+=2
            consts.append(data[p:p+ln].decode('utf-8','replace')); p+=ln
        elif tag in (7,8,16,19,20): consts.append(struct.unpack('>H',data[p:p+2])[0]); p+=2
        elif tag==15: consts.append(data[p:p+3]); p+=3
        elif tag in (3,4,9,10,11,12,17,18): consts.append(data[p:p+4]); p+=4
        elif tag in (5,6): consts.append(data[p:p+8]); p+=8; consts.append(None)
        else: raise ValueError(f'tag {tag}')
    p+=2 # flags
    p+=2 # this
    p+=2 # super
    ni=struct.unpack('>H',data[p:p+2])[0]; p+=2
    for _ in range(ni):
        p+=2; nc=struct.unpack('>H',data[p:p+2])[0]; p+=2+2*nc
    nf=struct.unpack('>H',data[p:p+2])[0]; p+=2
    for _ in range(nf):
        p+=6; na=struct.unpack('>H',data[p:p+2])[0]; p+=2+2*na
    nm=struct.unpack('>H',data[p:p+2])[0]; p+=2
    out=[]
    for _ in range(nm):
        flags,name,desc=struct.unpack('>HHH',data[p:p+6]); p+=6
        na=struct.unpack('>H',data[p:p+2])[0]; p+=2
        for _ in range(na):
            alen=struct.unpack('>I',data[p:p+4])[0]; p+=4+alen
        if name==7 and desc==5: out.append('public static void main(String[])')
    return out

for j in glob.glob('/opt/tools/lib/igv/*.jar'):
