        self.mapq=int(p[4]); self.tlen=int(p[8]); self.seq=p[9]; self.qual=p[10]
        self.blocks=[]; self.dels=[]; self.aligned_len=0
        r=self.pos0; q=0
        for m in CIG.finditer(p[5]):
            n=int(m.group(1)); op=m.group(2)
            if op in 'M=X':
                self.blocks.append((r,r+n,q,q+n)); r += n; q += n; self.aligned_len += n
            elif op=='I': q += n
            elif op=='D':
                self.dels.append(normalize_deletion(r,r+n)); r += n
            elif op=='N': r += n
            elif op=='S': q += n
    def covers(self,pos1):
        p=pos1-1
        return any(a <= p < b for a,b,_,__ in self.blocks)
    def base_at(self,pos1):
        p=pos1-1
        for a,b,qs,qe in self.blocks:
            if a <= p < b:
                i=qs+p-a
                return self.seq[i], ord(self.qual[i])-33
        return None
    def mismatches(self,exclude_pos=None):
        ex = None if exclude_pos is None else exclude_pos-1
        n=0
        for a,b,qs,qe in self.blocks:
            for r,q in zip(range(a,b),range(qs,qe)):
                if r != ex and self.seq[q] != REF[r]: n += 1
        return n
    def distance_to_end_for_pos(self,pos1):
        p=pos1-1
        for a,b,qs,qe in self.blocks:
            if a <= p < b:
                qi=qs+p-a
                return min(qi, len(self.seq)-1-qi)
        return None
    def distance_to_end_for_deletion(self,ds,de):
        # Distance of the deleted span from the closest aligned/read terminus.
        return min(ds-self.pos0, self.end0()-(de-1))
    def end0(self):
        return max((b for _,b,_,__ in self.blocks), default=self.pos0)

def event(read,c):
    ref=c['ref']; alt=c['alt']; pos=c['pos']
    if len(ref)==len(alt)==1:
        b=read.base_at(pos)
        if b and b[0]==alt:
            return {'type':'SNV','qual':b[1],'end_dist':read.distance_to_end_for_pos(pos)}
        return None
    # Deletion candidate: anchor at POS; deleted reference bases begin at POS+1.
    ds=pos; de=pos+len(ref)-1
    target=normalize_deletion(ds,de)
    if any(d == target for d in read.dels):
        anchor=read.base_at(pos)
        return {'type':'DEL','qual':anchor[1] if anchor else None,
                'end_dist':read.distance_to_end_for_deletion(target[0],target[1])}
    return None

def load(path):
    pairs=defaultdict(list)
    excluded=Counter()
    for line in open(path):
        p=line.rstrip('\n').split('\t')
        flag=int(p[1])
        if flag & 0x100: excluded['secondary'] += 1; continue
        if flag & 0x800: excluded['supplementary'] += 1; continue
        if flag & 0x400: excluded['duplicate'] += 1; continue
        pairs[p[0]].append(Read(p))
    return list(pairs.values()), excluded

# Pre-filter records to a generous region around candidates for speed.
lo=min(c['pos'] for c in CANDS)-200
hi=max(c['pos'] for c in CANDS)+200
def load_window(path):
    pairs=defaultdict(list); excluded=Counter()
    for line in open(path):
        p=line.rstrip('\n').split('\t')
        flag=int(p[1]); pos=int(p[3])
        if not (lo <= pos <= hi): continue
        if flag & 0x100: excluded['secondary'] += 1; continue
        if flag & 0x800: excluded['supplementary'] += 1; continue
        if flag & 0x400: excluded['duplicate'] += 1; continue
        pairs[p[0]].append(Read(p))
    return list(pairs.values()), excluded

def metrics(mols,c):
    depth=[]; support=[]
    for rr in mols:
        cover=[r for r in rr if r.covers(c['pos'])]
        ev=[(r,event(r,c)) for r in rr]
        ev=[x for x in ev if x[1]]
        if cover: depth.append((rr,cover))
        if ev:
            # Include every read of the molecule that covers the candidate.
            reads=cover if cover else [r for r,_ in ev]
            support.append((rr,reads,ev))
    out={
        'depth_mols':len(depth), 'alt_mols':len(support),
        'support_reads':len(support_reads(support)),
    }
    return out,depth,support

def support_reads(support):
    seen=set(); out=[]
    for _,reads,_ in support:
        for r in reads:
            k=(r.name,r.flag,r.pos0,r.cigar_id if hasattr(r,'cigar_id') else id(r))
            # Names are unique within sample, and each molecule has two reads.
            if r.name not in seen:
                pass
        # Use all listed reads; molecules have unique read names and distinct mate records.
        out.extend(reads)
    return out

def detailed(mols,c):
    m,depth,support=metrics(mols,c)
    reads=[]
    for _,rr,_ in support: reads.extend(rr)
    bq=[]; mq_min=[]; mq_all=[]; mismatch=[]; ends=[]; fwd=rev=0; disc=0
    for rr,cover,evs in support:
        qualities=[]
        for r,e in evs:
            if e['qual'] is not None: qualities.append(e['qual'])
        if qualities: bq.append(min(qualities))
        mqs=[r.mapq for r in cover]
        mq_min.append(min(mqs)); mq_all.extend(mqs)
        # Exclude the candidate alternate base for SNVs. For deletions the alternate
        # bases are not aligned, so there is nothing to exclude.
        mismatch.extend(r.mismatches(c['pos'] if len(c['ref'])==len(c['alt'])==1 else None) for r in cover)
        ends.extend(e['end_dist'] is not None and e['end_dist'] < 5 for _,e in evs)
        for r in cover:
            if r.flag & 16: rev += 1
            else: fwd += 1
        if any(abs(r.tlen)>1000 for r in rr): disc += 1
    n=len(support)
    out=dict(m)
    out.update({
        'low_bq_mols':sum(x<20 for x in bq), 'bq_available':len(bq),
        'low_mq_min_mols':sum(x<20 for x in mq_min),
        'low_mq_any_mols':sum(any(x<20 for x in [r.mapq for r in cover]) for rr,cover,_ in support),
        'mean_mismatch':sum(mismatch)/len(mismatch) if mismatch else 0,
        'end_reads':sum(ends), 'read_count':len(reads),
        'fwd':fwd, 'rev':rev, 'discordant_mols':disc
    })
    return out

def classify(d):
    germline = d['n_alt_mols'] >= 2 and d['n_depth_mols'] and d['n_alt_mols']/d['n_depth_mols'] >= .05
    if germline: return 'GERMLINE',germline
    if d['alt_mols'] < 4: return 'LOW_SUPPORT',germline
    if d['bq_available'] and d['low_bq_mols'] >= .75*d['bq_available']: return 'LOW_BASE_QUALITY',germline
    if d['low_mq_min_mols'] >= .75*d['alt_mols']: return 'LOW_MAPPING_QUALITY',germline
    if d['mean_mismatch'] >= 4: return 'MULTI_MISMATCH',germline
    total=d['fwd']+d['rev']
    if total and (d['fwd']/total >= .9 or d['rev']/total >= .9) and d['fwd']>0 and d['rev']>0:
        return 'STRAND_BIAS',germline
    if d['read_count'] and d['end_reads'] >= .75*d['read_count']: return 'READ_END',germline
    if d['alt_mols'] and d['discordant_mols'] >= .75*d['alt_mols']: return 'DISCORDANT_PAIRS',germline
    return None,germline

